-- NEXUS v0.4.0 optional OpenOS .shrc autostart manager.
-- EXPLICIT OPT-IN: /home/nexus-startup.lua enable YES
-- Run /home/nexus-startup.lua disable to restore normal OpenOS shell startup.
local fs=require('filesystem')
local argv={...}
local command=argv[1] or 'status'
local shrc='/home/.shrc'
local boot='/home/nexus40-bootstrap.lua'
local core='/home/nexus40.lua'
local guard='/home/nexus/startup.guard'
local BEGIN='# NEXUS-STARTUP BEGIN'
local END='# NEXUS-STARTUP END'
local block=BEGIN..'\n'..boot..'\n'..END..'\n'
local bootstrap=[[
-- NEXUS-BOOTSTRAP v0.4.0 (generated by nexus_startup.lua)
local fs=require('filesystem')
local core='/home/nexus40.lua'
local guard='/home/nexus/startup.guard'
if fs.exists(guard) then
  io.write('NEXUS autostart recovery: previous attempt was unclean.\n')
  io.write('OpenOS is available. Use nexus-startup.lua recover when ready.\n')
  return
end
local f,why=io.open(guard,'w')
if not f then io.write('NEXUS autostart guard unavailable: '..tostring(why)..'\n');return end
f:write('startup pending\n');f:close()
local ok,success,reason=pcall(dofile,core)
if ok and success==true then
  fs.remove(guard)
else
  io.write('NEXUS startup failed: '..tostring(ok and reason or success)..'\n')
  io.write('Autostart will be skipped next time until recovery.\n')
end
]]
local function read(path)
  local f=io.open(path,'r');if not f then return nil end
  local value=f:read(16385);f:close();return value
end
local function write(path,value)
  local f,why=io.open(path,'w');if not f then return false,why end
  local ok,err=pcall(function()assert(f:write(value));assert(f:flush())end)
  f:close();return ok,err
end
local function atomic(path,data)
  local temp=path..'.nexus-tmp'
  local ok,err=write(temp,data);if not ok then return false,err end
  local old=path..'.nexus-prev'
  if fs.exists(old) then fs.remove(old) end
  local had=fs.exists(path)
  if had then
    local moved,why=fs.rename(path,old)
    if not moved then fs.remove(temp);return false,why end
  end
  local installed,why=fs.rename(temp,path)
  if not installed then
    if had then fs.rename(old,path) end
    return false,why
  end
  -- Recovery backup retained in *.nexus-prev.
  return true
end
local raw=read(shrc) or ''
local hasBegin=raw:find(BEGIN,1,true)
local hasEnd=raw:find(END,1,true)
if command=='status' then
  print('NEXUS autostart: '..(hasBegin and hasEnd and 'ENABLED' or 'DISABLED'))
  print('Recovery guard: '..(fs.exists(guard) and 'PRESENT (autostart skips)' or 'clear'))
  print('Boot file: '..(fs.exists(core) and 'found' or 'missing'))
elseif command=='enable' then
  if argv[2]~='YES' then print('To enable, run: nexus-startup.lua enable YES');return end
  if not fs.exists(core) then print('ERROR: '..core..' is missing');return end
  if #raw>8192 then print('ERROR: .shrc too large; manual review required');return end
  if hasBegin or hasEnd then print('ERROR: NEXUS markers already present; inspect .shrc');return end
  if fs.exists(boot) then
    local existing=read(boot)
    if not existing or not existing:find('NEXUS-BOOTSTRAP v0.4.0',1,true) then
      print('ERROR: bootstrap exists but is not owned by NEXUS');return
    end
  end
  if not fs.exists(boot) then
    local ok,why=write(boot,bootstrap);if not ok then print('ERROR: '..tostring(why));return end
  end
  local new=raw
  if #new>0 and new:sub(-1)~='\n' then new=new..'\n' end
  local ok,why=atomic(shrc,new..block)
  if ok then print('ENABLED: NEXUS launches on next OpenOS interactive shell startup.')
  else print('ERROR: '..tostring(why)) end
elseif command=='disable' then
  if not hasBegin and not hasEnd then print('Already disabled');return end
  local start=hasBegin;local stop=hasEnd
  if not start or not stop or stop<=start then print('ERROR: invalid markers; manual review required');return end
  local after=stop+#END
  if raw:sub(after+1,after+1)=='\n' then after=after+1 end
  local updated=raw:sub(1,start-1)..raw:sub(after+1)
  local ok,why=atomic(shrc,updated)
  if ok then print('DISABLED: OpenOS shell startup restored; other .shrc lines kept.')
  else print('ERROR: '..tostring(why)) end
elseif command=='recover' then
  if fs.exists(guard) then
    local ok,why=fs.remove(guard)
    print(ok and 'Recovery guard cleared; inspect NEXUS error before reattempting.' or ('ERROR: '..tostring(why)))
  else print('Guard already clear') end
else print('Usage: nexus-startup.lua status | enable YES | disable | recover') end
